/**
 * @name Pickle Data Flow
 * @description Analyze data flow to pickle.load/loads in cookiejar.py
 * @kind path-problem
 * @problem.severity error
 * @id py/pickle-data-flow
 * @tags security
 *       external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module PickleConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // We want to see where the data comes from, so we'll look for parameter nodes or file reads
    // that eventually reach the pickle sink.
    exists(DataFlow::ParameterNode p | source = p) or
    source = API::moduleImport("builtins").getMember("open").getACall()
  }

  predicate isSink(DataFlow::Node sink) {
     sink = API::moduleImport("pickle").getMember(["load", "loads"]).getACall().getArg(0)
  }
}

module PickleFlow = TaintTracking::Global<PickleConfig>;
import PickleFlow::PathGraph

from PickleFlow::PathNode source, PickleFlow::PathNode sink
where PickleFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Pickle data from $@.", source.getNode(), "source"

