/**
 * @name Open Redirect
 * @description Detects potential open redirects where the Location header is user-controlled
 * @kind path-problem
 * @problem.severity error
 * @id py/open-redirect
 * @tags security
 *       external/cwe/cwe-601
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module OpenRedirectConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // Checks for HTTPFound, HTTPMovedPermanently, etc. which are subclasses of Response
      // and take 'location' as the first argument or keyword argument.
      // Also web.Response(headers={'Location': ...})
      (
        call = API::moduleImport("aiohttp").getMember("web").getMember(["HTTPFound", "HTTPMovedPermanently", "HTTPSeeOther", "HTTPTemporaryRedirect", "HTTPPermanentRedirect"]).getACall() and
        (sink = call.getArg(0) or sink = call.getArgByName("location"))
      )
    )
  }
}

module OpenRedirectFlow = TaintTracking::Global<OpenRedirectConfig>;
import OpenRedirectFlow::PathGraph

from OpenRedirectFlow::PathNode source, OpenRedirectFlow::PathNode sink
where OpenRedirectFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Open redirect from $@.", source.getNode(), "user input"

/**
 * @name Reflected XSS
 * @description Detects potential XSS in web.Response
 * @kind path-problem
 * @problem.severity error
 * @id py/reflected-xss
 * @tags security
 *       external/cwe/cwe-079
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module ReflectedXSSConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("aiohttp").getMember("web").getMember("Response").getACall() and
      (
        sink = call.getArgByName("text") or 
        sink = call.getArgByName("body")
      )
      // Ideally we should check content_type is html, but let's be broad first.
      // aiohttp web.Response(text=...) defaults to text/plain, 
      // but if content_type="text/html" is set, it is XSS. 
      // This query is a bit noisy as it catches text/plain too.
    )
  }
}

