/**
 * @name Pickle Load Data Flow
 * @description Taint tracking to see where the file argument to pickle.load comes from in CookieJar
 * @kind path-problem
 * @problem.severity error
 * @id py/pickle-load-source
 * @tags security
 *       external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module PickleLoadConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Look for parameters of methods in CookieJar class
    exists(Function f, Class c |
      f.getScope() = c and
      c.getName() = "CookieJar" and
      source = DataFlow::parameterNode(f.getArg(0)) // self is 0, first arg is 1 usually, but getArg counts formals
    )
    or
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pickle").getMember("load").getACall() and
      sink = call.getArg(0)
    )
  }
}

module PickleLoadFlow = TaintTracking::Global<PickleLoadConfig>;
import PickleLoadFlow::PathGraph

from PickleLoadFlow::PathNode source, PickleLoadFlow::PathNode sink
where PickleLoadFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Pickle load from $@.", source.getNode(), "parameter"

